# Largest element offset an int32 index can hold. Larger tensors take the tiled
# kernel's 64-bit index path.
_INT32_MAX = 2**31 - 1

# GCU400 grid.x hardware limit; every launch below stays at or under it.
_GRID_CAP = 65535

# Tuned on GCU400 (see R01..R10 in the optimization report).
_LANE_BLOCK = 512
_LANE_WARPS = 2
_TILE_ELEMS = 16384
_TILE_BO_CAP = 128
_TILE_WARPS = 8
# Lane form wins on large output counts over narrow windows.
_LANE_MIN_TOTAL = 8192
_LANE_MAX_KVOL = 256


@triton.jit
def _pool3d_lane_body(
    in_ptr,
    out_ptr,
    C,
    D_in,
    H_in,
    W_in,
    D_out,
    H_out,
    W_out,
    stride_in_n,
    stride_in_c,
    stride_in_d,
    stride_in_h,
    stride_in_w,
    stride_out_n,
    stride_out_c,
    stride_out_d,
    stride_out_h,
    stride_out_w,
    TOTAL,
    block_id,
    MAX_D: tl.constexpr,
    MAX_H: tl.constexpr,
    MAX_W: tl.constexpr,
    BLOCK: tl.constexpr,
    USE_I64: tl.constexpr,
):
    """Pool one block of BLOCK flat output elements (one lane per output)."""
    # IDX is int32 whenever a flat offset fits: GCU400 emulates 64-bit integer
    # divide/modulo in scalar code, which dominates this body's cost.
    IDX: tl.constexpr = tl.int64 if USE_I64 else tl.int32
    arange = tl.arange(0, BLOCK)
    D_out_i = tl.full((), D_out, IDX)
    H_out_i = tl.full((), H_out, IDX)
    W_out_i = tl.full((), W_out, IDX)
    C_i = tl.full((), C, IDX)
    D_in_i = tl.full((), D_in, IDX)
    H_in_i = tl.full((), H_in, IDX)
    W_in_i = tl.full((), W_in, IDX)
    s_in_n = tl.full((), stride_in_n, IDX)
    s_in_c = tl.full((), stride_in_c, IDX)
    s_in_d = tl.full((), stride_in_d, IDX)
    s_in_h = tl.full((), stride_in_h, IDX)
    s_in_w = tl.full((), stride_in_w, IDX)
    s_out_n = tl.full((), stride_out_n, IDX)
    s_out_c = tl.full((), stride_out_c, IDX)
    s_out_d = tl.full((), stride_out_d, IDX)
    s_out_h = tl.full((), stride_out_h, IDX)
    s_out_w = tl.full((), stride_out_w, IDX)

    offs = block_id * BLOCK + arange
    mask = offs < TOTAL
    offs_i = offs.to(IDX)

    # Unravel the flat output index -> (n, c, d_o, h_o, w_o).
    w_o = offs_i % W_out_i
    idx = offs_i // W_out_i
    h_o = idx % H_out_i
    idx = idx // H_out_i
    d_o = idx % D_out_i
    idx = idx // D_out_i
    c = idx % C_i
    n = idx // C_i

    d0 = (d_o * D_in_i) // D_out_i
    d1 = ((d_o + 1) * D_in_i + D_out_i - 1) // D_out_i
    h0 = (h_o * H_in_i) // H_out_i
    h1 = ((h_o + 1) * H_in_i + H_out_i - 1) // H_out_i
    w0 = (w_o * W_in_i) // W_out_i
    w1 = ((w_o + 1) * W_in_i + W_out_i - 1) // W_out_i

    nd = d1 - d0
    nh = h1 - h0
    nw = w1 - w0
    denom = (nd * nh * nw).to(tl.float32)

    base = n * s_in_n + c * s_in_c

    acc = tl.zeros((BLOCK,), dtype=tl.float32)
    for di in range(MAX_D):
        dmask = mask & (di < nd)
        for hi in range(MAX_H):
            dhmask = dmask & (hi < nh)
            for wi in range(MAX_W):
                wmask = dhmask & (wi < nw)
                in_idx = (
                    base + (d0 + di) * s_in_d + (h0 + hi) * s_in_h + (w0 + wi) * s_in_w
                )
                val = tl.load(in_ptr + in_idx, mask=wmask, other=0.0)
                acc += val.to(tl.float32)

    out_idx = n * s_out_n + c * s_out_c + d_o * s_out_d + h_o * s_out_h + w_o * s_out_w
    tl.store(out_ptr + out_idx, acc / denom, mask=mask)


@triton.jit
def _pool3d_tile_body(
    in_ptr,
    out_ptr,
    stride_in_n,
    stride_in_c,
    stride_in_d,
    stride_in_h,
    stride_in_w,
    stride_out_n,
    stride_out_c,
    stride_out_d,
    stride_out_h,
    stride_out_w,
    row_block,
    SPEC: tl.constexpr,
    USE_I64: tl.constexpr,
):
    """Pool one row-block of BO output elements over BR window offsets."""
    TOTAL: tl.constexpr = SPEC[0]
    C: tl.constexpr = SPEC[1]
    D_in: tl.constexpr = SPEC[2]
    H_in: tl.constexpr = SPEC[3]
    W_in: tl.constexpr = SPEC[4]
    D_out: tl.constexpr = SPEC[5]
    H_out: tl.constexpr = SPEC[6]
    W_out: tl.constexpr = SPEC[7]
    K_D: tl.constexpr = SPEC[8]
    K_H: tl.constexpr = SPEC[9]
    K_W: tl.constexpr = SPEC[10]
    BO: tl.constexpr = SPEC[11]
    BR: tl.constexpr = SPEC[12]

    IDX: tl.constexpr = tl.int64 if USE_I64 else tl.int32
    s_in_n = tl.full((), stride_in_n, IDX)
    s_in_c = tl.full((), stride_in_c, IDX)
    s_in_d = tl.full((), stride_in_d, IDX)
    s_in_h = tl.full((), stride_in_h, IDX)
    s_in_w = tl.full((), stride_in_w, IDX)
    s_out_n = tl.full((), stride_out_n, IDX)
    s_out_c = tl.full((), stride_out_c, IDX)
    s_out_d = tl.full((), stride_out_d, IDX)
    s_out_h = tl.full((), stride_out_h, IDX)
    s_out_w = tl.full((), stride_out_w, IDX)

    K_VOL: tl.constexpr = K_D * K_H * K_W

    out = row_block * BO + tl.arange(0, BO)
    out64 = out.to(IDX)
    # W_out / H_out / D_out / C are compile-time constants here, so this unravel
    # folds into constant multiplies.
    w_o = out64 % W_out
    h_o = out64 // W_out % H_out
    d_o = out64 // (W_out * H_out) % D_out
    nc = out64 // (W_out * H_out * D_out)
    n = nc // C
    c = nc % C

    w0 = w_o * W_in // W_out
    h0 = h_o * H_in // H_out
    d0 = d_o * D_in // D_out
    w1 = ((w_o + 1) * W_in + W_out - 1) // W_out
    h1 = ((h_o + 1) * H_in + H_out - 1) // H_out
    d1 = ((d_o + 1) * D_in + D_out - 1) // D_out

    base = n * s_in_n + c * s_in_c
    acc = tl.zeros((BO, BR), dtype=tl.float32)
    for start in range(tl.cdiv(K_VOL, BR)):
        r = start * BR + tl.arange(0, BR)
        kd = (r // (K_H * K_W)).to(IDX)
        kh = (r // K_W % K_H).to(IDX)
        kw = (r % K_W).to(IDX)
        di = d0[:, None] + kd[None, :]
        hi = h0[:, None] + kh[None, :]
        wi = w0[:, None] + kw[None, :]
        mask = (
            (out[:, None] < TOTAL)
            & (r[None, :] < K_VOL)
            & (di < d1[:, None])
            & (hi < h1[:, None])
            & (wi < w1[:, None])
        )
        in_idx = base[:, None] + di * s_in_d + hi * s_in_h + wi * s_in_w
        acc += tl.load(in_ptr + in_idx, mask, other=0.0).to(tl.float32)

    denom = ((d1 - d0) * (h1 - h0) * (w1 - w0)).to(tl.float32)
    out_val = tl.sum(acc, 1) / denom
    out_idx = n * s_out_n + c * s_out_c + d_o * s_out_d + h_o * s_out_h + w_o * s_out_w
    tl.store(out_ptr + out_idx, out_val, mask=out < TOTAL)


