def _tile_meta(k_d, k_h, k_w):
    """Pick (BO, BR, num_warps): BR covers the window volume, BO the remainder.

    A wide window therefore gets most of the tile and few rows, while a narrow
    window gets many rows, so one shape covers both the small-output and the
    large-output cases without a host-side branch.
    """
    br = min(triton.next_power_of_2(k_d * k_h * k_w), _TILE_ELEMS // 2)
    bo = min(_TILE_BO_CAP, max(1, _TILE_ELEMS // br))
    # A tile of only a few hundred elements is launch-bound: four warps beat
    # eight there, because the eighth warp has no work left to overlap.
    warps = _TILE_WARPS if bo * br > 1024 else 4
    return bo, br, warps


def _window_bound(in_size, out_size):
    """Upper bound on an adaptive pooling window's extent along one axis."""
    return triton.cdiv(in_size, out_size) + (in_size % out_size != 0)


def _normalize_output_size_3d(output_size):
    if isinstance(output_size, torch.Size):
        output_size = tuple(output_size)
    if isinstance(output_size, (list, tuple)):
        if len(output_size) != 3:
            raise ValueError(
                "output_size for _adaptive_avg_pool3d must have 3 elements (D_out, H_out, W_out)"
            )
        return tuple(int(x) for x in output_size)
    raise TypeError("output_size must be a sequence of three integers")


def _prepare_5d_input(t):
    if t.dim() == 5:
        return t, False
    if t.dim() == 4:
        return t.unsqueeze(0), True  # add N=1
    raise ValueError(
        "input for _adaptive_avg_pool3d must be 4D (C,D,H,W) or 5D (N,C,D,H,W)"
    )


def _launch_adaptive_avg_pool3d_kernel(x, out):
    N, C, D_in, H_in, W_in = x.shape
    D_out, H_out, W_out = out.shape[-3], out.shape[-2], out.shape[-1]

    stride_in_n, stride_in_c, stride_in_d, stride_in_h, stride_in_w = x.stride()
    stride_out_n, stride_out_c, stride_out_d, stride_out_h, stride_out_w = out.stride()

    total = N * C * D_out * H_out * W_out
    if total == 0:
        return

    max_d = _window_bound(D_in, D_out)
    max_h = _window_bound(H_in, H_out)
    max_w = _window_bound(W_in, W_out)
    k_vol = max_d * max_h * max_w

    # Lane form wins on large output counts over narrow windows; the tiled form
    # wins whenever the window is wide enough to keep its columns busy, and is
    # the only workable shape for a tiny output over a huge window. The
    # crossover follows the measured GCU400 sweep in the optimization report.
    use_lane = total >= _LANE_MIN_TOTAL and k_vol <= _LANE_MAX_KVOL
    # int64 offsets only when a flat index can actually exceed 2^31.
    use_i64 = max(x.numel(), out.numel()) > _INT32_MAX

    with torch_device_fn.device(x.device):
        if use_lane:
            block = _LANE_BLOCK
            num_blocks = triton.cdiv(total, block)
            multi = num_blocks > _GRID_CAP
            grid = (min(num_blocks, _GRID_CAP),)
            adaptive_avg_pool3d_lane_kernel[grid](
                x,
                out,
                C,
                D_in,
                H_in,
                W_in,
                D_out,
                H_out,
                W_out,
                stride_in_n,
                stride_in_c,
                stride_in_d,
                stride_in_h,
                stride_in_w,
                stride_out_n,
                stride_out_c,
                stride_out_d,
                stride_out_h,
                stride_out_w,
                total,
                MAX_D=max_d,
                MAX_H=max_h,
                MAX_W=max_w,
                BLOCK=block,
                MULTI=multi,
                USE_I64=use_i64,
                num_warps=_LANE_WARPS,
            )
        else:
            bo, br, tile_warps = _tile_meta(max_d, max_h, max_w)
            num_blocks = triton.cdiv(total, bo)
            multi = num_blocks > _GRID_CAP
            grid = (min(num_blocks, _GRID_CAP),)
            adaptive_avg_pool3d_tile_kernel[grid](
                x,
                out,
                stride_in_n,
                stride_in_c,
                stride_in_d,
                stride_in_h,
                stride_in_w,
                stride_out_n,
                stride_out_c,
                stride_out_d,
                stride_out_h,
                stride_out_w,
                (
                    total,
                    C,
                    D_in,
                    H_in,
                    W_in,
                    D_out,
                    H_out,
                    W_out,
                    max_d,
                    max_h,
                    max_w,
                    bo,
                    br,
                ),
                USE_I64=use_i64,
                MULTI=multi,
                num_warps=tile_warps,
            )
    return


def _adaptive_avg_pool3d(input: torch.Tensor, output_size):
    logger.debug("GEMS_ENFLAME _ADAPTIVE_AVG_POOL3D")
    x5d, squeezed = _prepare_5d_input(input)
    D_out, H_out, W_out = _normalize_output_size_3d(output_size)

    N, C, D_in, H_in, W_in = x5d.shape
    out_shape_5d = (N, C, D_out, H_out, W_out)
    out5d = torch.empty(
        out_shape_5d, device=x5d.device, dtype=x5d.dtype, layout=x5d.layout
    )

    _launch_adaptive_avg_pool3d_kernel(x5d, out5d)

    if squeezed:
        return out5d.squeeze(0)
    return out5d


def _adaptive_avg_pool3d_out(input: torch.Tensor, output_size, out: torch.Tensor):
    logger.debug("GEMS_ENFLAME _ADAPTIVE_AVG_POOL3D_OUT")
    x5d, squeezed = _prepare_5d_input(input)
    D_out, H_out, W_out = _normalize_output_size_3d(output_size)

    # Prepare out to be 5D if needed
    if squeezed:
        if out.dim() == 4:
            out5d = out.unsqueeze(0)
        elif out.dim() == 5 and out.size(0) == 1:
            out5d = out
        else:
            raise ValueError("Provided 'out' must be 4D (C,D,H,W) when input is 4D")
    else:
        out5d = out
        if out5d.dim() != 5:
            raise ValueError("Provided 'out' must be 5D (N,C,D,H,W) when input is 5D")

    # Validate shape
    expected_shape = (x5d.size(0), x5d.size(1), D_out, H_out, W_out)
    if tuple(out5d.shape) != expected_shape:
        raise ValueError(
            f"out has incorrect shape. Expected {expected_shape}, got {tuple(out5d.shape)}"
        )

    if out5d.device != x5d.device or out5d.dtype != x5d.dtype:
        raise ValueError(
            "out must be on the same device and have the same dtype as input"
        )

    _launch_adaptive_avg_pool3d_kernel(x5d, out5d)

    return out
